import os

# Load all grids from session logs
session_dir = os.environ.get('RLM_SESSION_DIR', '')
if session_dir:
    session_log = os.path.join(session_dir, '..', 'sessions', os.path.basename(session_dir) + '.jsonl')
    with open(session_log, 'r') as f:
        log_text = f.read()

    # Find demo pairs and test input
    grids = {}
    in_grid = None
    grid_name = None
    grid_dims = None

    lines = log_text.split('\n')
    i = 0
    while i < len(lines):
        line = lines[i]
        if 'Demo pair' in line or 'Test input' in line:
            # Extract grid name and dimensions
            m = re.search(r'(Demo pair|\sTest input)\s+(\w+)\s+(\d+)x(\d+):\n', line)
            if m:
                grid_name = m.group(2)
                grid_dims = (int(m.group(3)), int(m.group(4)))

                # Read the grid cells
                i += 1
                while i < len(lines):
                    cells_line = lines[i]
                    if cells_line.strip():
                        if grid_name == 'Test input' and cells_line.strip().startswith('Wrong attempts'):
                            break

                        if cells_line.strip() and cells_line.strip()[0].isdigit():
                            rows = cells_line.strip().split()
