def transform(grid):
    """Move all non-background cells down to pack into bottom 3 rows (6,7,8)"""
    height = len(grid)
    width = len(grid[0])
    result = [[0] * width for _ in range(height)]

    # Copy the bottom row
    for c in range(width):
        result[height - 1][c] = grid[height - 1][c]

    for c in range(width):
        cells = []
        for r in range(height - 1):
            if grid[r][c] != 0:
                cells.append((r, grid[r][c]))

        cells.sort()
        num_cells = len(cells)

        for i, (orig_row, val) in enumerate(cells):
            if num_cells > 1:
                band_index = i
            else:
                if orig_row <= 1:
                    band_index = 0
                elif orig_row <= 3:
                    band_index = 1
                else:
                    band_index = 2

            band_index = max(0, min(2, band_index))
            target_row = 6 + band_index
            result[target_row][c] = val

    return result

