# Let me try: each column gets 3 output rows (6,7,8)
# Values from input are distributed based on their position from the marker
# Rows closest to marker → bottom output row (8)
# Middle rows → middle output row (7)
# Rows furthest from marker → top output row (6)

def transform_band_mapping(grid, marker_row):
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]

    # Copy marker
    for c in range(w):
        result[marker_row][c] = grid[marker_row][c]

    # For each column, collect non-zero values with their band assignment
    for c in range(w):
        band0_vals = []  # furthest from marker (0-2)
        band1_vals = []  # middle (3-5)
        band2_vals = []  # closest (6-8)

        for r in range(h):
            if r == marker_row:
                continue
            if grid[r][c] != 0:
                # Determine band based on distance from marker
                r_rel = r if marker_row == h-1 else (h - 1 - r)  # distance from bottom
                if r_rel <= 2:
                    band2_vals.append(grid[r][c])
                elif r_rel <= 5:
                    band1_vals.append(grid[r][c])
                else:
                    band0_vals.append(grid[r][c])

        # Place in output rows: band0→6, band1→7, band2→8
        for v in band0_vals:
            result[6][c] = v
        for v in band1_vals:
            result[7][c] = v
        for v in band2_vals:
            result[8][c] = v

    return result

# Test on demo
